blocks.code:
type SectionId = 'identity' | 'address' | 'income' | 'review';

type FieldName =
  | 'firstName'
  | 'lastName'
  | 'dateOfBirth'
  | 'ssn'
  | 'street'
  | 'city'
  | 'state'
  | 'postalCode'
  | 'annualIncome'
  | 'monthlyHousingCost'
  | 'termsAccepted';

interface FieldState {
  value: string;
  touched: boolean;
  error: string | null;
  sensitive: boolean;
}

type SubmitPhase = 'idle' | 'submitting' | 'submitted' | 'failed';

interface FormStoreState {
  section: SectionId;
  fields: Record<FieldName, FieldState>;
  idempotencyKey: string | null;
  submitPhase: SubmitPhase;
}

type DecisionStatus = 'approved' | 'declined' | 'pending-review' | 'verify-identity';

interface MaskedSummary {
  fullName: string;
  ssnLast4: string;
  cityAndState: string;
}

interface ApplicationRecord {
  applicationId: string;
  status: DecisionStatus;
  summary: MaskedSummary;
  creditLimit: number | null;
  updatedAt: string;
}
